FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION admin.calculate_haversine_distance_km(DOUBLE PRECISION, DOUBLE PRECISION, DOUBLE PRECISION, DOUBLE PRECISION) TO service_role;

